import { API } from './api.js';
import { Utils } from './utils.js';

export const isCheckoutPage = pathname => /^\/payment(?:\/|$)/i.test(pathname || '');
export const isBundleTask = task => task?.listingType === 'bundle'
    || task?.isBundle === true
    || /\/(?:bundles)\//i.test(task?.url || '')
    || (typeof task?.name === 'string' && /\bbundle\b/i.test(task.name));

export function freeBundleOffers(listing) {
    if (listing?.listingType !== 'bundle') return [];
    const offers = (listing.licenses || []).filter(license => {
        const tier = license?.priceTier;
        const price = tier?.discountedPrice ?? tier?.price;
        const offerId = license?.offerId || license?.offer_id;
        const isFree = (typeof price === 'number' && price === 0)
            || tier?.effectiveDiscountPercentage === 100
            || license?.isCc0 === true;
        return isFree && typeof offerId === 'string' && offerId;
    }).map(license => license.offerId || license.offer_id);

    if (offers.length > 0) return offers;

    const sp = listing?.startingPrice;
    if (sp) {
        const spPrice = sp.discountedPrice ?? sp.price;
        const spOffer = sp.offerId || sp.offer_id;
        if (typeof spPrice === 'number' && spPrice === 0 && typeof spOffer === 'string' && spOffer) {
            return [spOffer];
        }
    }
    return [];
}

/** Validate the exact purchase URL generated by Fab's Buy now button.
 * The namespace is supplied by Fab, never guessed from the listing UID.
 */
export function bundleCheckoutUrl(src, offers) {
    try {
        const url = new URL(src, 'https://www.fab.com');
        if (url.origin !== 'https://www.fab.com' || url.pathname !== '/payment/web/purchase') return null;
        const match = url.searchParams.get('offers')?.match(/^1-[a-f0-9]{32}-([a-f0-9]{32})--$/i);
        if (!match || !offers.includes(match[1])) return null;
        return url.href;
    } catch { return null; }
}

export function isZeroPriceCheckout(text = '') {
    const amounts = [...text.matchAll(/(?:[$€£¥￥]|USD|EUR|GBP|CNY)\s*(\d[\d.,]*)/g)];
    return amounts.length > 0 && amounts.every(match => /^0+(?:[.,]0+)?$/.test(match[1]));
}

const buttonText = button => (button.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
const libraryLabels = new Set(['add to library', 'add to my library', '添加到库', '添加到我的库', '加入我的库']);

/** Bundle uses the official zero-price checkout, not /add-to-library (which returns 400).
 * Keep the native parent/iframe handshake intact. The worker submits the free
 * checkout button once, then verifies ownership through listings-states.
 */
export async function acquireBundle(task, options = {}) {
    const doc = options.doc ?? document;
    const win = options.win ?? window;
    const api = options.api || API;
    const utils = options.utils || Utils;
    const sleep = options.sleep || (ms => new Promise(resolve => setTimeout(resolve, ms)));
    const now = options.now || Date.now;
    const log = options.log || (() => {});
    const fail = (reason, extra = {}) => { log(`[Bundle] ${reason}`); return { success: false, reason, ...extra }; };
    const get = async url => {
        const response = await api.gmFetch({ method: 'GET', url, headers: {
            accept: 'application/json', 'x-requested-with': 'XMLHttpRequest',
            'x-csrftoken': utils.getCookie('fab_csrftoken') || ''
        } });
        if (response.status === 429) {
            const err = new Error('接口返回 429');
            err.rateLimited = true;
            const retry = response.getResponseHeader?.('retry-after')
                || response.responseHeaders?.match(/retry-after:\s*(\d+)/i)?.[1];
            err.retryAfterMs = retry ? Number(retry) * 1000 : null;
            throw err;
        }
        if (response.status !== 200) throw new Error(`接口返回 ${response.status || '未知状态'}`);
        return JSON.parse(response.responseText);
    };
    const owned = async () => {
        const payload = await get(`https://www.fab.com/i/users/me/listings-states?listing_ids=${encodeURIComponent(task.uid)}`);
        const states = Array.isArray(payload) ? payload : api.extractStateData(payload, 'BundleVerify');
        return Array.isArray(states) && states.some(state => state?.uid === task.uid && state.acquired === true);
    };

    try {
        if (!isBundleTask(task) && task?.listingType !== 'bundle' && !task?.isBundle) return fail('不是 bundle 任务');
        const listing = await get(`https://www.fab.com/i/listings/${encodeURIComponent(task.uid)}`);
        if (listing?.listingType === 'bundle') {
            task.listingType = 'bundle';
            task.isBundle = true;
        }
        const offers = freeBundleOffers(listing);
        if (!offers.length) return fail('未找到免费许可，停止领取');
        if (await owned()) return { success: true };
        if (isCheckoutPage(new URL(win.location.href).pathname)) return fail('请从 bundle 详情页启动领取');
        const openDeadline = now() + 30000;
        let clicked = false;
        let checkoutDoc = null;
        while (now() < openDeadline) {
            const frame = doc.querySelector('iframe[src*="/payment/web/purchase"]');
            if (frame) {
                if (!bundleCheckoutUrl(frame.getAttribute('src'), offers)) return fail('结算链接不是此 bundle 的免费许可');
                try { checkoutDoc = frame.contentDocument; }
                catch { return fail('需要人工操作跨域结算页，已保留页面', { manualRequired: true }); }
                if (checkoutDoc?.body && checkoutDoc.querySelector('button')) break;
            }
            if (!clicked) {
                const sidebar = doc.querySelector('aside, [role="complementary"]');
                const button = [...(sidebar?.querySelectorAll('button') || doc.querySelectorAll('button') || [])]
                    .find(item => !item.disabled && ['buy now', '立即购买'].includes(buttonText(item)));
                if (button) { utils.deepClick(button); clicked = true; log('[Bundle] 已打开官网免费结算入口'); }
            }
            await sleep(250);
        }
        if (!checkoutDoc?.body) return fail('未能加载 bundle 结算页');

        const deadline = now() + 45000;
        let submitted = false;
        let nextVerifyAt = 0;
        while (now() < deadline) {
            const visibleText = checkoutDoc.body?.innerText || '';
            const captcha = [...checkoutDoc.querySelectorAll('iframe[title*="challenge"], iframe[src*="frame=challenge"]')]
                .some(frame => { const rect = frame.getBoundingClientRect(); const style = checkoutDoc.defaultView?.getComputedStyle(frame); return rect.width > 0 && rect.height > 0 && style?.visibility !== 'hidden' && style?.display !== 'none'; });
            if (captcha || /verify you are human|请完成安全验证|确认您是真人/i.test(visibleText)) {
                return fail('需要人工完成人机验证，已保留结算页', { manualRequired: true });
            }
            if ([...checkoutDoc.querySelectorAll('input[type="checkbox"]')].some(input => !input.checked
                && (input.required || /agree|terms|eula|同意|协议/i.test(input.closest?.('label')?.textContent || '')))) {
                return fail('需要人工确认结算条款，已保留结算页', { manualRequired: true });
            }
            if (!submitted) {
                const button = [...checkoutDoc.querySelectorAll('button')].find(item => !item.disabled && libraryLabels.has(buttonText(item)));
                if (button) {
                    if (!isZeroPriceCheckout(visibleText)) return fail('结算页未确认零元金额，停止领取');
                    utils.deepClick(button);
                    submitted = true;
                    nextVerifyAt = now() + 2000;
                    log('[Bundle] 已点击零元添加到库，等待服务端确认');
                }
            } else if (now() >= nextVerifyAt) {
                if (await owned()) { log('[Bundle] 服务端确认已入库'); return { success: true }; }
                nextVerifyAt = now() + 2000;
            }
            await sleep(250);
        }
        return fail(submitted ? '结算后服务端未确认入库' : '结算页未出现零元添加到库按钮');
    } catch (error) {
        return fail(error.message, error.rateLimited ? { rateLimited: true, retryAfterMs: error.retryAfterMs } : {});
    }
}
